      if(comparisonId){const base=snapshot.cases.find(c=>c.id===comparisonId);if(base)computed.comparison=compareScenarios(base.result,computed);}computed.historyRevision=snapshot.revision||0;computed.recordsRevision=recordState?.impactRevision||0;result=computed;step=3;error='';saveDraft();draw();root.scrollTop=0;root.querySelector('.formal-decision h2')?.focus({preventScroll:true});
